import java.sql.*;

public class SecureDatabaseAccess {
    public void authenticateUser(String username, String password) {
        String query = "SELECT * FROM users WHERE username = ? AND password = ?";

        // Using PreparedStatement to prevent SQL injection
        try (Connection conn = DriverManager.getConnection("jdbc:mysql://localhost:3306/mydb", "user", "pass");
             PreparedStatement pstmt = conn.prepareStatement(query)) {

            pstmt.setString(1, username); // Safe parameter binding
            pstmt.setString(2, password); // Safe parameter binding

            try (ResultSet rs = pstmt.executeQuery()) {
                if (rs.next()) {
                    System.out.println("Authentication successful.");
                } else {
                    System.out.println("Authentication failed.");
                }
            }
        } catch (SQLException e) {
            e.printStackTrace();
        }
    }
}
